# Generates public test certificates and signed PDFs with OpenSSL 4.0.3.
# Keys exist only in a temporary directory; regenerated bytes and dates differ.
from pathlib import Path
import subprocess,tempfile,shutil
p=Path(__file__).resolve().parent;p.mkdir(exist_ok=True)
def run(*args):subprocess.run(args,check=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
with tempfile.TemporaryDirectory() as work:
 w=Path(work)
 run('openssl','req','-x509','-newkey','rsa:2048','-nodes','-keyout',str(w/'root.key'),'-out',str(w/'root.pem'),'-subj','/CN=Docmill Test Root','-days','3650')
 shutil.copy(w/'root.pem',p/'root.pem')
 (w/'ext').write_text('basicConstraints=critical,CA:FALSE\nkeyUsage=critical,digitalSignature\nextendedKeyUsage=codeSigning\n')
 for algo in ['rsa','ecdsa']:
  if algo=='rsa':run('openssl','genpkey','-algorithm','RSA','-pkeyopt','rsa_keygen_bits:2048','-out',str(w/'key'))
  else:run('openssl','genpkey','-algorithm','EC','-pkeyopt','ec_paramgen_curve:P-256','-out',str(w/'key'))
  run('openssl','req','-new','-key',str(w/'key'),'-out',str(w/'csr'),'-subj','/CN=Docmill '+algo+' signer')
  run('openssl','x509','-req','-in',str(w/'csr'),'-CA',str(w/'root.pem'),'-CAkey',str(w/'root.key'),'-CAcreateserial','-out',str(w/'cert'),'-days','365','-extfile',str(w/'ext'))
  shutil.copy(w/'cert',p/(algo+'.pem'))
  for profile in (['rsa','pss','cades'] if algo=='rsa' else ['ecdsa']):
   subtype='ETSI.CAdES.detached' if profile=='cades' else 'adbe.pkcs7.detached'
   data=b'%PDF-1.7\n';offsets=[0]
   bodies=[b'<< /Type /Catalog /Pages 2 0 R /AcroForm 5 0 R >>',b'<< /Type /Pages /Count 1 /Kids [3 0 R] >>',b'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 200 200] /Contents 4 0 R >>',b'<< /Length 0 >>\nstream\n\nendstream',b'<< /Fields [6 0 R] >>',b'<< /FT /Sig /T (approval) /V 7 0 R >>',b'<< /Type /Sig /Filter /Adobe.PPKLite /SubFilter /'+subtype.encode()+b' /ByteRange [0000000000 0000000000 0000000000 0000000000] /Contents <'+b'0'*16384+b'> >>']
   for i,body in enumerate(bodies,1):offsets.append(len(data));data+=str(i).encode()+b' 0 obj\n'+body+b'\nendobj\n'
   xref=len(data);data+=b'xref\n0 8\n0000000000 65535 f \n'
   for off in offsets[1:]:data+=f'{off:010d} 00000 n \n'.encode()
   data+=f'trailer << /Size 8 /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n'.encode()
   start=data.index(b'/Contents <')+len(b'/Contents ');end=data.index(b'>',start)+1
   old=b'[0000000000 0000000000 0000000000 0000000000]';new=f'[0000000000 {start:010d} {end:010d} {len(data)-end:010d}]'.encode();data=data.replace(old,new)
   (w/'content').write_bytes(data[:start]+data[end:])
   args=['openssl','cms','-sign','-binary','-md','sha256','-in',str(w/'content'),'-signer',str(w/'cert'),'-inkey',str(w/'key'),'-certfile',str(w/'root.pem'),'-outform','DER','-out',str(w/'signature')]
   if profile=='cades':args+=['-cades']
   if profile=='pss':args+=['-keyopt','rsa_padding_mode:pss','-keyopt','rsa_pss_saltlen:digest']
   run(*args)
   cms=(w/'signature').read_bytes().hex().encode();assert len(cms)<end-start-2
   data=data[:start+1]+cms+b'0'*(end-start-2-len(cms))+data[end-1:]
   (p/(profile+'.pdf')).write_bytes(data)
   run('openssl','cms','-verify','-binary','-inform','DER','-in',str(w/'signature'),'-content',str(w/'content'),'-CAfile',str(w/'root.pem'),'-purpose','any','-out',str(w/'verified'))

   if profile=='rsa':
    second=data+b'\n'
    pos5=len(second);second+=b'5 0 obj\n<< /Fields [6 0 R 9 0 R] >>\nendobj\n'
    pos9=len(second);second+=b'9 0 obj\n<< /FT /Sig /T (second) /V 10 0 R >>\nendobj\n'
    pos10=len(second);second+=b'10 0 obj\n<< /Type /Sig /Filter /Adobe.PPKLite /SubFilter /adbe.pkcs7.detached /ByteRange [0000000000 0000000000 0000000000 0000000000] /Contents <'+b'0'*16384+b'> >>\nendobj\n'
    nextxref=len(second)
    second+=f'xref\n5 1\n{pos5:010d} 00000 n \n9 2\n{pos9:010d} 00000 n \n{pos10:010d} 00000 n \ntrailer << /Size 11 /Root 1 0 R /Prev {xref} >>\nstartxref\n{nextxref}\n%%EOF\n'.encode()
    start2=second.rfind(b'/Contents <')+len(b'/Contents ');end2=second.index(b'>',start2)+1
    second=second.replace(old,f'[0000000000 {start2:010d} {end2:010d} {len(second)-end2:010d}]'.encode())
    (w/'content2').write_bytes(second[:start2]+second[end2:])
    run('openssl','cms','-sign','-binary','-md','sha256','-in',str(w/'content2'),'-signer',str(w/'cert'),'-inkey',str(w/'key'),'-certfile',str(w/'root.pem'),'-outform','DER','-out',str(w/'signature2'))
    cms2=(w/'signature2').read_bytes().hex().encode();assert len(cms2)<end2-start2-2
    second=second[:start2+1]+cms2+b'0'*(end2-start2-2-len(cms2))+second[end2-1:]
    (p/'multiple.pdf').write_bytes(second)
    run('openssl','cms','-verify','-binary','-inform','DER','-in',str(w/'signature2'),'-content',str(w/'content2'),'-CAfile',str(w/'root.pem'),'-purpose','any','-out',str(w/'verified'))

# BER permits indefinite outer containers; signed attributes remain untouched.
def frame(data):
 length=data[1];start=2
 if length&128:
  count=length&127;length=int.from_bytes(data[start:start+count],'big');start+=count
 return start,start+length

def wrap_ber(data,depth=0):
 start,end=frame(data)
 if not data[0]&32 or depth>=3:return data[:end]
 content=data[start:end];children=b''
 while content:
  a,b=frame(content);children+=wrap_ber(content[:b],depth+1);content=content[b:]
 return data[:1]+b'\x80'+children+b'\x00\x00'

rsa=(p/'rsa.pdf').read_bytes();start=rsa.index(b'/Contents <')+len(b'/Contents <');end=rsa.index(b'>',start)
raw=bytes.fromhex(rsa[start:end].decode());a,b=frame(raw);wrapped=wrap_ber(raw[:b]);encoded=wrapped.hex().encode()
assert len(encoded)<=end-start
(p/'rsa-ber.pdf').write_bytes(rsa[:start]+encoded+b'0'*(end-start-len(encoded))+rsa[end:])
